import { Component, computed, inject, resource, signal } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { ResolucionService } from '../../../shared/services/resolucion.service';
import { NavigationHistoryService } from '../../../services/navigation-history.service';
import { SolicitudSnapshot, HistoricoSnapshotData, DocumentoSnapshot, Resolucion, ResolucionEstado } from '../../../shared/models/resolucion.model';
import { PdfViewerComponent } from '../../../shared/components/pdf-viewer/pdf-viewer.component';
import { statusToClass } from '../../../shared/models/solicitud-status.util';

@Component({
  selector: 'app-ver-historico',
  templateUrl: './ver-historico.component.html',
  styleUrls: ['./ver-historico.component.scss'],
  imports: [PdfViewerComponent],
})
export class VerHistoricoComponent {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly resolucionService = inject(ResolucionService);
  private readonly navHistory = inject(NavigationHistoryService);

  readonly origen = signal<'ejecutivo' | 'inversor'>(
    (this.route.snapshot.data['origen'] as 'ejecutivo' | 'inversor') ?? 'ejecutivo',
  );

  readonly snapshotResource = resource({
    params: () => ({ snapshotId: Number(this.route.snapshot.paramMap.get('snapshotId')) }),
    loader: async ({ params }) => {
      return await firstValueFrom(this.resolucionService.getSnapshotById(params.snapshotId));
    },
  });

  readonly snapshot = computed<SolicitudSnapshot | null>(() => {
    const state = window.history.state as { snapshot?: SolicitudSnapshot };
    if (state?.snapshot) return state.snapshot;
    if (this.snapshotResource.error()) return null;
    return this.snapshotResource.value() ?? null;
  });

  readonly data = computed<HistoricoSnapshotData>(() => this.snapshot()?.data ?? {});

  readonly folio = computed(() => (this.data()['folio'] as string) ?? '—');
  readonly status = computed(() => (this.data()['status'] as string) ?? '—');
  readonly fecha = computed(() => (this.data()['fecha_resolucion'] as string) ?? '—');
  readonly nombreProyecto = computed(() => (this.data()['nombre_proyecto'] as string) ?? '');
  readonly tieneSnapshot = computed(() => this.snapshot() !== null);

  readonly isFisica = computed(() => this.data()['personalidad_juridica'] === 'fisica');

  readonly nombreSolicitante = computed(() => {
    if (this.isFisica()) {
      return (this.data()['nombre_completo'] as string) ?? '—';
    }
    return (this.data()['denominacion_razon_social'] as string) ?? '—';
  });

  readonly documentos = computed(() => (this.data()['documentos'] as DocumentoSnapshot[]) ?? []);
  readonly observaciones = computed(() => (this.data()['observaciones'] as { texto: string; evaluador: string; fecha: string; status: string }[]) ?? []);

  readonly selectedDocId = signal<number | null>(null);
  readonly mostrarVisor = signal(false);
  readonly resolucion = computed<Resolucion | null>(() => {
    const snap = this.snapshot();
    if (!snap?.resolucion) return null;
    return {
      id: snap.resolucion.id,
      sentido: snap.resolucion.sentido,
      estado: snap.resolucion.estado as ResolucionEstado,
      tieneDocumento: snap.resolucion.tieneDocumento,
      fechaEmision: snap.resolucion.fechaEmision ?? undefined,
    };
  });
  readonly tieneDocumentoResolucion = computed(() => this.resolucion()?.tieneDocumento ?? false);

  statusToClass = statusToClass;

  goBack(): void {
    this.router.navigateByUrl(this.navHistory.getBackRoute(this.origen(), 'bandeja/recibidas'));
  }

  descargarResolucion(): void {
    const res = this.resolucion();
    const folioStr = this.folio();
    if (!res || !res.tieneDocumento || folioStr === '—') return;
    this.resolucionService.descargarResolucion(folioStr, res.id).subscribe({
      next: (blob) => {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `resolucion_${folioStr}_${res.id}.pdf`;
        a.click();
        URL.revokeObjectURL(url);
      },
    });
  }

  seleccionarDocumento(id: number): void {
    this.selectedDocId.set(id);
    this.mostrarVisor.set(true);
  }

  cerrarVisor(): void {
    this.mostrarVisor.set(false);
    this.selectedDocId.set(null);
  }
}
